// Tests for pfb_unbound_model.go. Each test names the Python test (or the Python-oracle run) it ports.
//
// Rows tagged "oracle" were generated by running the Python function on the same fixture (uv run python,
// Python 3.11, this worktree); they are pasted, never recomputed by Go code.
package decider

import (
	"fmt"
	"math/rand/v2"
	"regexp"
	"slices"
	"strings"
	"sync"
	"testing"
)

func mwLegacy(wildcard bool) whiteEntry { return whiteEntry{legacy: true, wildcard: wildcard} }

func mwDict(wildcard, important bool) whiteEntry {
	return whiteEntry{wildcard: wildcard, important: important}
}

func mwBand(wildcard, important bool, band int) whiteEntry {
	return whiteEntry{wildcard: wildcard, important: important, band: band, hasBand: true}
}

// test_adr07_matcher_strata.py TestPriorityBands.
func TestPriorityBands(t *testing.T) {
	for _, c := range []struct {
		important, user bool
		block, allow    int
	}{
		{false, false, PRIO_FEED_BLOCK, PRIO_FEED_ALLOW},
		{true, false, PRIO_FEED_BLOCK_IMPORTANT, PRIO_FEED_ALLOW_IMPORTANT},
		{false, true, PRIO_USER_BLOCK, PRIO_USER_ALLOW},
		{true, true, PRIO_USER_BLOCK, PRIO_USER_ALLOW}, // user wins over important (Python checks `user` first)
	} {
		if got := blockPriority(c.important, c.user); got != c.block {
			t.Errorf("blockPriority(%v, %v) = %d, want %d", c.important, c.user, got, c.block)
		}
		if got := allowPriority(c.important, c.user); got != c.allow {
			t.Errorf("allowPriority(%v, %v) = %d, want %d", c.important, c.user, got, c.allow)
		}
	}
	for want, got := range map[int]int{1: PRIO_FEED_BLOCK, 2: PRIO_FEED_ALLOW, 3: PRIO_FEED_BLOCK_IMPORTANT, 4: PRIO_FEED_ALLOW_IMPORTANT, 5: PRIO_USER_BLOCK, 6: PRIO_USER_ALLOW} {
		if got != want {
			t.Errorf("band constant = %d, want %d", got, want)
		}
	}
	// test_no_ties_block_odd_allow_even: the "no ties" guarantee rests on block in {1,3,5}, allow in {2,4,6}.
	for _, p := range []int{PRIO_FEED_BLOCK, PRIO_FEED_BLOCK_IMPORTANT, PRIO_USER_BLOCK} {
		if p%2 != 1 {
			t.Errorf("block band %d is not odd", p)
		}
	}
	for _, p := range []int{PRIO_FEED_ALLOW, PRIO_FEED_ALLOW_IMPORTANT, PRIO_USER_ALLOW} {
		if p%2 != 0 {
			t.Errorf("allow band %d is not even", p)
		}
	}
}

func TestBlockEntryBand(t *testing.T) {
	for _, band := range []int{PRIO_FEED_BLOCK, PRIO_FEED_BLOCK_IMPORTANT, PRIO_USER_BLOCK} {
		if got := blockEntryBand(&blockEntry{log: "1", index: 0, band: band}); got != band {
			t.Errorf("blockEntryBand(band %d) = %d", band, got)
		}
	}
	// test_regex_literal_prefilter.py reads the band of a regexDB payload the same way.
	entry := &blockEntry{log: "1", index: 9, important: true, band: blockPriority(true, false)}
	if got := blockEntryBand(entry); got != PRIO_FEED_BLOCK_IMPORTANT {
		t.Errorf("blockEntryBand(important feed block) = %d, want %d", got, PRIO_FEED_BLOCK_IMPORTANT)
	}
}

// test_adr07_matcher_strata.py TestWhiteEntryShape.test_wildcard_accessor / test_important_accessor, plus the band
// accessor rows (oracle: _white_entry_wildcard / _white_entry_important / _white_entry_band).
func TestWhiteEntryAccessors(t *testing.T) {
	for _, c := range []struct {
		name      string
		entry     whiteEntry
		wildcard  bool
		important bool
		band      int
	}{
		{"bare True", mwLegacy(true), true, false, 2},
		{"bare False", mwLegacy(false), false, false, 2},
		{"{}", whiteEntry{}, false, false, 2},
		{"wildcard only", whiteEntry{wildcard: true}, true, false, 2},
		{"important only (derived band)", whiteEntry{important: true}, false, true, 6},
		{"band 4 only", whiteEntry{band: 4, hasBand: true}, false, false, 4},
		{"explicit band beats important", whiteEntry{band: 2, hasBand: true, important: true}, false, true, 2},
		{"important False", whiteEntry{important: false}, false, false, 2},
		{"wildcard+important", mwDict(true, true), true, true, 6},
		{"wildcard False + important", mwDict(false, true), false, true, 6},
		{"wildcard + important False", mwDict(true, false), true, false, 2},
	} {
		if got := whiteEntryWildcard(c.entry); got != c.wildcard {
			t.Errorf("%s: whiteEntryWildcard = %v, want %v", c.name, got, c.wildcard)
		}
		if got := whiteEntryImportant(c.entry); got != c.important {
			t.Errorf("%s: whiteEntryImportant = %v, want %v", c.name, got, c.important)
		}
		if got := whiteEntryBand(c.entry); got != c.band {
			t.Errorf("%s: whiteEntryBand = %d, want %d", c.name, got, c.band)
		}
	}
}

// Oracle rows of _white_widen_entry: broadest wildcard, any important, max band, feed index dropped.
func TestWhiteWidenEntry(t *testing.T) {
	indexed := func(index int) whiteEntry {
		e := mwBand(false, false, 2)
		e.index, e.hasIndex = index, true
		return e
	}
	for _, c := range []struct {
		name          string
		existing, new whiteEntry
		want          whiteEntry
	}{
		{"True,False", mwLegacy(true), mwLegacy(false), mwBand(true, false, 2)},
		{"False,True", mwLegacy(false), mwLegacy(true), mwBand(true, false, 2)},
		{"True,True", mwLegacy(true), mwLegacy(true), mwBand(true, false, 2)},
		{"False,False", mwLegacy(false), mwLegacy(false), mwBand(false, false, 2)},
		{"dict,dict plain", mwDict(false, false), mwDict(false, false), mwBand(false, false, 2)},
		{"feed allow + user allow", mwBand(true, false, 2), mwBand(false, true, 6), mwBand(true, true, 6)},
		{"important feed allow + feed allow", mwBand(false, true, 4), mwBand(true, false, 2), mwBand(true, true, 4)},
		{"index dropped", indexed(7), indexed(9), mwBand(false, false, 2)},
		{"derived band 6 + bare wildcard", mwDict(false, true), mwLegacy(true), mwBand(true, true, 6)},
		{"band only", whiteEntry{band: 4, hasBand: true}, whiteEntry{band: 2, hasBand: true}, mwBand(false, false, 4)},
		{"wildcard only + bare False", whiteEntry{wildcard: true}, mwLegacy(false), mwBand(true, false, 2)},
	} {
		if got := whiteWidenEntry(c.existing, c.new); got != c.want {
			t.Errorf("%s: whiteWidenEntry = %+v, want %+v", c.name, got, c.want)
		}
	}
}

