// test_pfb_unbound.py TestEvaluateNoaaaa, test_adr06_build_module.py TestBuildNoAAAA, plus oracle rows
// (evaluate_noaaaa / find_noaaaa_wildcard_parent on one fixture, degenerate names included).
func TestEvaluateNoaaaa(t *testing.T) {
	for _, c := range []struct {
		name  string
		db    map[string]bool
		query string
		want  bool
	}{
		{"exact match, wildcard False", map[string]bool{"example.com": false}, "example.com", true},
		{"exact match, wildcard True", map[string]bool{"example.com": true}, "example.com", true},
		{"wildcard parent matches subdomain", map[string]bool{"example.com": true}, "sub.example.com", true},
		{"wildcard False does not match subdomain", map[string]bool{"example.com": false}, "sub.example.com", false},
		{"no match", map[string]bool{"other.com": true}, "example.com", false},
		{"deep wildcard parent", map[string]bool{"example.com": true}, "deep.sub.example.com", true},
	} {
		if got := evaluateNoaaaa(c.query, c.db); got != c.want {
			t.Errorf("%s: evaluateNoaaaa(%q) = %v, want %v", c.name, c.query, got, c.want)
		}
	}
	golden := map[string]bool{"noaaaa.com": false, "noaaaawild.net": true}
	for query, want := range map[string]bool{
		"noaaaa.com": true, "host.noaaaawild.net": true, "noaaaawild.net": true, "sub.noaaaa.com": false, "totally-unrelated.com": false,
	} {
		if got := evaluateNoaaaa(query, golden); got != want {
			t.Errorf("golden noAAAA list: evaluateNoaaaa(%q) = %v, want %v", query, got, want)
		}
	}
	oracle := map[string]bool{"example.com": true, "off.example": false, "wild.org": true, "": true}
	for _, r := range []struct {
		query    string
		evaluate bool
		parent   string
		hasParen bool
	}{
		{"example.com", true, "", false},
		{"sub.example.com", true, "example.com", true},
		{"a.b.example.com", true, "example.com", true},
		{"off.example", true, "", false},
		{"sub.off.example", false, "", false},
		{"wild.org", true, "", false},
		{"x.y.wild.org", true, "wild.org", true},
		{"x.y.z.wild.org", true, "wild.org", true},
		{"unrelated.net", false, "", false},
		{"", true, "", false},
		{"com", false, "", false},
		{"..", false, "", false},
		{"a.", false, "", false},
		{".a", false, "", false},
		{"a..example.com", true, "example.com", true},
		{".example.com", true, "example.com", true},
	} {
		if got := evaluateNoaaaa(r.query, oracle); got != r.evaluate {
			t.Errorf("oracle: evaluateNoaaaa(%q) = %v, want %v", r.query, got, r.evaluate)
		}
		parent, ok := findNoaaaaWildcardParent(r.query, oracle)
		if parent != r.parent || ok != r.hasParen {
			t.Errorf("oracle: findNoaaaaWildcardParent(%q) = (%q, %v), want (%q, %v)", r.query, parent, ok, r.parent, r.hasParen)
		}
	}
}

// test_pfb_unbound.py TestHstsCheckDomain plus oracle rows.
func TestHstsCheckDomain(t *testing.T) {
	set := func(names ...string) map[string]struct{} {
		db := map[string]struct{}{}
		for _, n := range names {
			db[n] = struct{}{}
		}
		return db
	}
	for _, c := range []struct {
		name    string
		db      map[string]struct{}
		tlds    []string
		query   string
		tld     string
		matched bool
		pType   string
	}{
		{"tld in hsts_tlds returns HSTS_TLD", set(), []string{"app"}, "example.app", "app", true, "HSTS_TLD"},
		{"tld not in hsts_tlds falls through", set(), []string{"app"}, "example.com", "com", false, "Python"},
		{"exact domain in hsts_db", set("example.com"), nil, "example.com", "com", true, "HSTS"},
		{"suffix walk hits parent", set("example.com"), nil, "sub.example.com", "com", true, "HSTS"},
		{"every parent suffix is checked (#713)", set("c.d"), nil, "a.b.c.d", "d", true, "HSTS"},
		{"second-level parent suffix matches", set("b.c.d"), nil, "a.b.c.d", "d", true, "HSTS"},
		{"bare TLD suffix is checked (#713)", set("d"), nil, "a.b.c.d", "d", true, "HSTS"},
		{"no match returns Python", set("other.com"), nil, "example.com", "com", false, "Python"},
	} {
		matched, pType := hstsCheckDomain(c.query, c.db, c.tlds, c.tld)
		if matched != c.matched || pType != c.pType {
			t.Errorf("%s: hstsCheckDomain(%q) = (%v, %q), want (%v, %q)", c.name, c.query, matched, pType, c.matched, c.pType)
		}
	}
	oracle := set("example.com", "c.d", "")
	for _, r := range []struct {
		query, tld string
		matched    bool
		pType      string
	}{
		{"example.com", "com", true, "HSTS"},
		{"sub.example.com", "com", true, "HSTS"},
		{"a.b.c.d", "d", true, "HSTS"},
		{"b.c.d", "d", true, "HSTS"},
		{"d", "d", false, "Python"},
		{"example.app", "app", true, "HSTS_TLD"},
		{"x.app", "app", true, "HSTS_TLD"},
		{"other.net", "net", false, "Python"},
		{"", "", true, "HSTS"},
		{"a..c.d", "d", true, "HSTS"},
		{"a.", "", true, "HSTS"},
	} {
		matched, pType := hstsCheckDomain(r.query, oracle, []string{"app"}, r.tld)
		if matched != r.matched || pType != r.pType {
			t.Errorf("oracle: hstsCheckDomain(%q, tld %q) = (%v, %q), want (%v, %q)", r.query, r.tld, matched, pType, r.matched, r.pType)
		}
	}
}

// test_pfb_unbound.py TestResolveFeedGroup. The None-index row is unreachable here: blockEntry.index is an int.
func TestResolveFeedGroup(t *testing.T) {
	db := map[int]feedGroup{0: {feed: "MyFeed", group: "MyGroup"}}
	if feed, group := resolveFeedGroup(0, db); feed != "MyFeed" || group != "MyGroup" {
		t.Errorf("resolveFeedGroup(0) = (%q, %q), want (MyFeed, MyGroup)", feed, group)
	}
	if feed, group := resolveFeedGroup(99, db); feed != "Unknown" || group != "Unknown" {
		t.Errorf("resolveFeedGroup(99) = (%q, %q), want (Unknown, Unknown)", feed, group)
	}
	if feed, group := resolveFeedGroup(99, nil); feed != "Unknown" || group != "Unknown" {
		t.Errorf("resolveFeedGroup(99, nil db) = (%q, %q), want (Unknown, Unknown)", feed, group)
	}
}

const (
	mwSeed    = 42
	mwEntries = 30
	mwQueries = 60
)

var (
	mwLabels = []string{"a", "bb", "cc", "example", "evil", "sub", "www", "foo", "bar", "xyz"}
	mwTlds   = []string{"com", "net", "org", "io"}
)

func mwRandDomain(rng *rand.Rand) string {
	n := rng.IntN(4) + 1
	parts := make([]string, 0, n)
	for range n - 1 {
		parts = append(parts, mwLabels[rng.IntN(len(mwLabels))])
	}
	return strings.Join(append(parts, mwTlds[rng.IntN(len(mwTlds))]), ".")
}

// test_pfb_unbound.py TestPureMatcherProperties: the matchers against brute-force references. Python's seeded
// random.Random stream is not reproducible from Go, so the Go rows draw from their own seeded generator.
func TestPureMatcherProperties(t *testing.T) {
	t.Run("find_zone_match", func(t *testing.T) {
		rng := rand.New(rand.NewPCG(mwSeed, 0))
		zone := map[string]*blockEntry{}
		for range mwEntries {
			zone[mwRandDomain(rng)] = &blockEntry{log: "1", band: 1}
		}
		for range mwQueries {
			q := mwRandDomain(rng)
			want := ""
			parts := strings.Split(q, ".")
			for i := range parts {
				if suffix := strings.Join(parts[i:], "."); zone[suffix] != nil {
					want = suffix
					break
				}
			}
			if got, _ := findZoneMatch(q, zone); got != want {
				t.Errorf("findZoneMatch(%q) = %q, want %q", q, got, want)
			}
		}
	})
	t.Run("whitelist_check_domain", func(t *testing.T) {
		rng := rand.New(rand.NewPCG(mwSeed+1, 0))
		white := map[string]whiteEntry{}
		for range mwEntries {
			white[mwRandDomain(rng)] = mwLegacy(rng.IntN(2) == 0)
		}
		const tldSeg = 2
		for range mwQueries {
			q := mwRandDomain(rng)
			_, want := white[q]
			if rest, found := strings.CutPrefix(q, "www."); !want && found {
				_, want = white[rest]
			}
			parts := strings.Split(q, ".")
			for i := 1; !want && i < len(parts); i++ {
				// i labels dropped leaves len(parts)-i labels in the suffix; only wildcard entries match here.
				e, ok := white[strings.Join(parts[i:], ".")]
				want = ok && len(parts)-i >= tldSeg && e.wildcard
			}
			if got := whitelistCheckDomain(q, white, tldSeg); got != want {
				t.Errorf("whitelistCheckDomain(%q) = %v, want %v", q, got, want)
			}
		}
	})
	t.Run("evaluate_noaaaa", func(t *testing.T) {
		rng := rand.New(rand.NewPCG(mwSeed+2, 0))
		db := map[string]bool{}
		for range mwEntries {
			db[mwRandDomain(rng)] = rng.IntN(2) == 0
		}
		for range mwQueries {
			q := mwRandDomain(rng)
			_, want := db[q] // the exact branch is a presence check, the wildcard flag is irrelevant
			parts := strings.Split(q, ".")
			// The wildcard branch starts at the parent and stops before the bare TLD; a wildcard-False value is falsy.
			for i := 1; !want && i < len(parts)-1; i++ {
				want = db[strings.Join(parts[i:], ".")]
			}
			if got := evaluateNoaaaa(q, db); got != want {
				t.Errorf("evaluateNoaaaa(%q) = %v, want %v", q, got, want)
			}
		}
	})
}

// The ordered regex DB stands in for a Python dict: first-matching-rule-wins walks it in insertion order, and
// re-assigning an existing key keeps its place.
func TestRegexDB(t *testing.T) {
	entry := func(pattern string, band int) *regexEntry {
		return &regexEntry{re: regexp.MustCompile(pattern), band: band}
	}
	db := &regexDB{}
	db.set("zeta", entry("z", PRIO_FEED_BLOCK))
	db.set("alpha", entry("a", PRIO_FEED_BLOCK))
	db.set("mid", entry("m", PRIO_FEED_BLOCK))
	replacement := entry("A", PRIO_FEED_BLOCK_IMPORTANT)
	db.set("alpha", replacement) // Python: dict[key] = new keeps the original position
	var names []string
	for name, e := range db.items() {
		names = append(names, name)
		if name == "alpha" && e != replacement {
			t.Errorf("items() yielded the stale entry for alpha")
		}
	}
	if want := []string{"zeta", "alpha", "mid"}; !slices.Equal(names, want) {
		t.Errorf("items() order = %q, want %q", names, want)
	}
	if db.len() != 3 {
		t.Errorf("len() = %d, want 3", db.len())
	}
	if got, ok := db.get("alpha"); !ok || got != replacement {
		t.Errorf("get(alpha) = (%v, %v), want the replacement", got, ok)
	}
	if got, ok := db.get("missing"); ok || got != nil {
		t.Errorf("get(missing) = (%v, %v), want (nil, false)", got, ok)
	}
	count := 0
	for range db.items() {
		count++
		break
	}
	if count != 1 {
		t.Errorf("breaking out of items() ran %d iterations, want 1", count)
	}
	// An absent Python dict is falsy and iterates empty; the nil DB is the same.
	var none *regexDB
	if none.len() != 0 {
		t.Errorf("nil regexDB len() = %d, want 0", none.len())
	}
	if got, ok := none.get("alpha"); ok || got != nil {
		t.Errorf("nil regexDB get = (%v, %v), want (nil, false)", got, ok)
	}
	for name := range none.items() {
		t.Errorf("nil regexDB yielded %q", name)
	}
}

// test_pfb_unbound.py TestLruCache.
func TestLruCache(t *testing.T) {
	t.Run("get_set_contains_len", func(t *testing.T) {
		c := newLruCache[int](0)
		if c.contains("a") {
			t.Error("empty cache contains a")
		}
		if v, ok := c.get("a"); ok || v != 0 {
			t.Errorf("get(a) on empty = (%d, %v), want (0, false)", v, ok)
		}
		c.set("a", 1)
		if v, ok := c.get("a"); !c.contains("a") || !ok || v != 1 || c.len() != 1 {
			t.Errorf("after set(a, 1): contains=%v get=(%d, %v) len=%d", c.contains("a"), v, ok, c.len())
		}
	})
	t.Run("unbounded_when_maxsize_zero", func(t *testing.T) {
		c := newLruCache[int](0)
		for i := range 1000 {
			c.set(fmt.Sprint(i), i)
		}
		if c.len() != 1000 {
			t.Errorf("len = %d, want 1000", c.len())
		}
	})
	t.Run("evicts_lru_at_cap", func(t *testing.T) {
		c := newLruCache[int](2)
		c.set("a", 1)
		c.set("b", 2)
		c.set("c", 3)
		if c.contains("a") || !c.contains("b") || !c.contains("c") || c.len() != 2 {
			t.Errorf("a=%v b=%v c=%v len=%d, want a absent, b/c present, len 2", c.contains("a"), c.contains("b"), c.contains("c"), c.len())
		}
	})
	t.Run("get_bumps_recency_keeps_hot", func(t *testing.T) {
		c := newLruCache[int](2)
		c.set("a", 1)
		c.set("b", 2)
		if v, _ := c.get("a"); v != 1 {
			t.Errorf("get(a) = %d, want 1", v)
		}
		c.set("c", 3)
		if !c.contains("a") || c.contains("b") || !c.contains("c") {
			t.Errorf("a=%v b=%v c=%v, want a/c present, b absent", c.contains("a"), c.contains("b"), c.contains("c"))
		}
	})
	t.Run("contains_does_not_bump", func(t *testing.T) {
		c := newLruCache[int](2)
		c.set("a", 1)
		c.set("b", 2)
		c.contains("a") // Python __contains__ is a plain `key in dict`
		c.set("c", 3)
		if c.contains("a") {
			t.Error("contains(a) bumped a to most-recent; a should have been evicted")
		}
	})
	t.Run("setitem_existing_bumps_recency", func(t *testing.T) {
		c := newLruCache[int](2)
		c.set("a", 1)
		c.set("b", 2)
		c.set("a", 10)
		c.set("c", 3)
		if v, ok := c.get("a"); !ok || v != 10 || c.contains("b") || !c.contains("c") {
			t.Errorf("a=(%d, %v) b=%v c=%v, want a==10, b absent, c present", v, ok, c.contains("b"), c.contains("c"))
		}
	})
	t.Run("clear_and_delitem", func(t *testing.T) {
		c := newLruCache[int](0)
		c.set("a", 1)
		c.set("b", 2)
		if !c.delete("a") || c.contains("a") {
			t.Error("delete(a) did not remove a")
		}
		if c.delete("a") {
			t.Error("deleting a missing key reported success")
		}
		c.clear()
		if c.len() != 0 || c.contains("b") {
			t.Errorf("after clear: len=%d contains(b)=%v", c.len(), c.contains("b"))
		}
		c.set("x", 1) // a cleared cache stays usable
		if v, ok := c.get("x"); !ok || v != 1 {
			t.Errorf("get(x) after clear = (%d, %v)", v, ok)
		}
	})
	t.Run("setMaxsize_evicts_one_on_next_set", func(t *testing.T) {
		// Python assigns decisionDB.maxsize (pfb_unbound.py:1929); __setitem__ then pops ONE entry per call.
		c := newLruCache[int](0)
		for i := range 5 {
			c.set(fmt.Sprint(i), i)
		}
		c.setMaxsize(3)
		if c.len() != 5 {
			t.Errorf("shrinking maxsize evicted eagerly: len = %d, want 5", c.len())
		}
		c.set("5", 5)
		if c.len() != 5 || c.contains("0") || !c.contains("1") {
			t.Errorf("len = %d contains(0)=%v contains(1)=%v, want 5, false, true (one pop per set)", c.len(), c.contains("0"), c.contains("1"))
		}
	})
	t.Run("concurrent_use_is_race_free_and_capped", func(t *testing.T) {
		// test_adr10_concurrency.py: get()+move_to_end() is compound; the per-instance lock makes it safe.
		const maxSize = 8
		c := newLruCache[int](maxSize)
		var wg sync.WaitGroup
		for g := range 8 {
			wg.Add(1)
			go func() {
				defer wg.Done()
				for i := range 500 {
					key := fmt.Sprint((g*31 + i) % 50)
					c.set(key, i)
					c.get(key)
					c.contains(key)
					if i%97 == 0 {
						c.delete(key)
					}
				}
			}()
		}
		wg.Wait()
		if got := c.len(); got > maxSize {
			t.Errorf("len = %d, exceeds cap %d", got, maxSize)
		}
	})
}

// test_pfb_unbound.py TestStage2UnifiedDecision.test_operate_respects_decisiondb_cap (cache level) and the
// issue #1074 generation tests (test_stale_generation_write_cannot_extend_a_live_memo,
// test_older_generation_straggler_neither_evicts_nor_extends).
func TestDecisionFor(t *testing.T) {
	found := &dnsblDecision{isFound: true, logType: "1", bType: "DNSBL", pType: "Python", feed: "F", group: "G", bEval: "evil.com"}
	allow := &dnsblDecision{nullBlocking: true}
	t.Run("a new name creates and stores an unevaluated memo stamped with the generation", func(t *testing.T) {
		db := newLruCache[*decision](0)
		dec := decisionFor(db, "evil.com", 7)
		if dec.snapGen != 7 || dec.getDnsbl() != UNSET || dec.getNoaaaa() != UNSET || dec.getSafesearch() != UNSET {
			t.Errorf("new memo = gen %d dnsbl %v noaaaa %v safesearch %v, want gen 7 and every axis UNSET", dec.snapGen, dec.getDnsbl(), dec.getNoaaaa(), dec.getSafesearch())
		}
		if stored, ok := db.get("evil.com"); !ok || stored != dec {
			t.Errorf("memo not stored: got (%p, %v), want %p", stored, ok, dec)
		}
		if again := decisionFor(db, "evil.com", 7); again != dec {
			t.Error("same generation returned a different memo")
		}
	})
	t.Run("a later generation replaces an older resident memo without inheriting its verdict", func(t *testing.T) {
		db := newLruCache[*decision](0)
		stale := newDecision(5)
		stale.setDnsbl(found)
		db.set("evil.com", stale)
		replacement := decisionFor(db, "evil.com", 6)
		if replacement == stale {
			t.Fatal("the stale memo was reused")
		}
		if stored, _ := db.get("evil.com"); stored != replacement || replacement.snapGen != 6 || replacement.getDnsbl() != UNSET {
			t.Errorf("replacement = gen %d dnsbl %v, stored %p want %p", replacement.snapGen, replacement.getDnsbl(), stored, replacement)
		}
		if stale.getDnsbl() != found {
			t.Error("the replaced memo was mutated")
		}
	})
	t.Run("an older-generation straggler neither evicts nor extends the newer memo", func(t *testing.T) {
		db := newLruCache[*decision](0)
		resident := decisionFor(db, "evil.com", 9)
		resident.setDnsbl(allow)
		straggler := decisionFor(db, "evil.com", 4)
		if straggler == resident || straggler.snapGen != 4 {
			t.Fatalf("straggler = %p gen %d, want a throwaway memo at gen 4", straggler, straggler.snapGen)
		}
		straggler.setDnsbl(found)
		if stored, _ := db.get("evil.com"); stored != resident || resident.getDnsbl() != allow {
			t.Errorf("resident was disturbed: stored %p want %p, dnsbl %v", stored, resident, resident.getDnsbl())
		}
	})
	t.Run("the memo is bounded by the cache cap", func(t *testing.T) {
		db := newLruCache[*decision](1)
		decisionFor(db, "one.com", 1)
		if db.len() != 1 {
			t.Errorf("len after one.com = %d, want 1", db.len())
		}
		decisionFor(db, "two.com", 1)
		if db.len() != 1 || !db.contains("two.com") || db.contains("one.com") {
			t.Errorf("len=%d two.com=%v one.com=%v, want 1, true, false", db.len(), db.contains("two.com"), db.contains("one.com"))
		}
	})
}

func TestDecisionAxes(t *testing.T) {
	dec := newDecision(3)
	if dec.snapGen != 3 {
		t.Errorf("snapGen = %d, want 3", dec.snapGen)
	}
	if dec.getDnsbl() != UNSET || dec.getNoaaaa() != UNSET || dec.getSafesearch() != UNSET {
		t.Error("a new Decision must start with every axis UNSET")
	}
	verdict := &dnsblDecision{isFound: true}
	dec.setDnsbl(verdict)
	dec.setNoaaaa(false) // an evaluated allow is distinct from UNSET
	dec.setSafesearch(nil)
	if dec.getDnsbl() != verdict {
		t.Errorf("dnsbl = %v, want the stored verdict", dec.getDnsbl())
	}
	if got := dec.getNoaaaa(); got == UNSET || got != false {
		t.Errorf("noaaaa = %v, want false (evaluated), not UNSET", got)
	}
	if got := dec.getSafesearch(); got == UNSET || got != nil {
		t.Errorf("safesearch = %v, want nil (evaluated no-match), not UNSET", got)
	}
	// Python mutates the axes under the GIL; Go guards each axis with the Decision's mutex.
	shared := newDecision(1)
	var wg sync.WaitGroup
	for range 4 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := range 500 {
				shared.setDnsbl(&dnsblDecision{isFound: i%2 == 0})
				shared.setNoaaaa(i%2 == 0)
				shared.setSafesearch(i)
				_, _, _ = shared.getDnsbl(), shared.getNoaaaa(), shared.getSafesearch()
			}
		}()
	}
	wg.Wait()
}
